// Customises the Android project generated by `npx cap add android`:
//   * landscape orientation, * immersive full-screen + keep screen on, * launcher icons.
// Run after `npx cap add android` and before building the APK. Safe to run repeatedly.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

export function patchManifest(xml) {
  if (xml.includes('android:screenOrientation')) return xml;
  return xml.replace('<activity', '<activity\n            android:screenOrientation="sensorLandscape"');
}

export function mainActivitySource(pkg) {
  return `package ${pkg};

import android.os.Bundle;
import android.view.WindowManager;
import androidx.core.view.WindowCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.core.view.WindowInsetsControllerCompat;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
  @Override
  public void onCreate(Bundle savedInstanceState) {
    super.onCreate(savedInstanceState);
    getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
    hideSystemBars();
  }

  @Override
  public void onWindowFocusChanged(boolean hasFocus) {
    super.onWindowFocusChanged(hasFocus);
    if (hasFocus) hideSystemBars();
  }

  private void hideSystemBars() {
    WindowCompat.setDecorFitsSystemWindows(getWindow(), false);
    WindowInsetsControllerCompat c = WindowCompat.getInsetsController(getWindow(), getWindow().getDecorView());
    c.setSystemBarsBehavior(WindowInsetsControllerCompat.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);
    c.hide(WindowInsetsCompat.Type.systemBars());
  }
}
`;
}

function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out); else out.push(p);
  }
  return out;
}

function copyDir(src, dst) {
  for (const file of walk(src)) {
    const target = path.join(dst, path.relative(src, file));
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.copyFileSync(file, target);
  }
}

export function prepare(root = process.cwd()) {
  const android = path.join(root, 'android');
  if (!fs.existsSync(android)) throw new Error('android/ not found - run "npx cap add android" first');
  const main = path.join(android, 'app', 'src', 'main');

  const manifest = path.join(main, 'AndroidManifest.xml');
  fs.writeFileSync(manifest, patchManifest(fs.readFileSync(manifest, 'utf8')));

  const activity = walk(path.join(main, 'java')).find((f) => f.endsWith('MainActivity.java'));
  if (!activity) throw new Error('MainActivity.java not found');
  const pkg = /^package\s+([\w.]+);/m.exec(fs.readFileSync(activity, 'utf8'))[1];
  fs.writeFileSync(activity, mainActivitySource(pkg));

  const res = path.join(main, 'res');
  const icons = path.join(root, 'resources', 'android');
  if (fs.existsSync(icons)) copyDir(icons, res);
  fs.mkdirSync(path.join(res, 'values'), { recursive: true });
  fs.writeFileSync(path.join(res, 'values', 'ic_launcher_background.xml'),
    '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="ic_launcher_background">#0E5C38</color>\n</resources>\n');
  console.log('Android project prepared (landscape, immersive, icons).');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) prepare();
export const _file = fileURLToPath(import.meta.url);
